package com.erudit.quiz.service;import com.erudit.integration.*;import com.erudit.integration.InternalClients.*;import com.erudit.integration.InternalContracts.Notification;import com.erudit.quiz.model.CompetitionModels.*;import com.erudit.quiz.repository.CompetitionRepository;import io.github.resilience4j.circuitbreaker.CircuitBreakerRegistry;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.ObjectProvider;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class CompetitionService {private final CompetitionRepository repository;private final ObjectProvider<UserClient> users;private final ObjectProvider<NotificationClient> notifications;private final CircuitBreakerRegistry breakers;
 @Transactional public Competition create(String title,UUID owner){return repository.create(title,owner);}
 @Transactional public void invite(UUID competition,UUID user,UUID actor){UserClient client=users.getIfAvailable();if(client!=null&&!ResilientExecutor.execute(breakers.circuitBreaker("internal"),()->client.get(user).active(),()->false))throw new IllegalStateException("User service unavailable");repository.invite(competition,user,actor);NotificationClient notifier=notifications.getIfAvailable();if(notifier!=null)ResilientExecutor.execute(breakers.circuitBreaker("internal"),()->{notifier.enqueue(new Notification(user,"COMPETITION_INVITE",Map.of("competitionId",competition.toString())));return true;},()->false);}
 @Transactional public void join(UUID competition,UUID user){repository.join(competition,user);}public List<Rating> leaderboard(UUID id){return repository.leaderboard(id);}public List<Rating> ratings(String period){return repository.ratings(period);}
}
